def backward_ok(old, new):
    problems = []
    for name, f in new.items():
        if name not in old and "default" not in f:
            problems.append(f"새 필드 {name} 에 기본값 없음")
        elif name in old and old[name]["type"] != f["type"]:
            problems.append(f"{name} 형식 {old[name]['type']} -> {f['type']}")
    return problems or ["OK"]

v1 = {"vin": {"type": "string"}, "ts": {"type": "long"}, "speed": {"type": "float"}}
v2 = dict(v1, soc={"type": "float", "default": None})
v3 = dict(v1, soc={"type": "float"})
v4 = dict(v1, speed={"type": "int"})
for name, s in [("v2", v2), ("v3", v3), ("v4", v4)]:
    print(name, backward_ok(v1, s))
# v2 ['OK']
# v3 ['새 필드 soc 에 기본값 없음']
# v4 ['speed 형식 float -> int']

import statistics

def flag(counts, th=3.5):
    med = statistics.median(counts)
    mad = statistics.median(abs(x - med) for x in counts)
    return [(d, x, round(0.6745 * (x - med) / mad, 1))
            for d, x in enumerate(counts, 1)
            if abs(0.6745 * (x - med) / mad) > th]

rows = [1020, 990, 1005, 1012, 998, 1031, 640, 1008, 2950, 1001]
print(flag(rows))
# [(7, 640, -22.5), (9, 2950, 119.2)]
